  if (!Array.isArray(widths) || widths.length === 0 || !widths.every((w) => Number.isInteger(w) && w >= 1)) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }
  const columns = widths.length;
  let alignments;
  if (align !== undefined) {
    if (!Array.isArray(align) || align.length !== columns) {
      throw new TableError('BAD_ALIGN', `align must have ${columns} entries`);
    }
    for (const value of align) {
      if (!ALIGNMENTS.has(value)) throw new TableError('BAD_ALIGN', `unknown alignment: ${value}`);
    }
    alignments = align;
  } else {
    alignments = new Array(columns).fill('left');
  }
  if (!Array.isArray(rows)) throw new TableError('BAD_ROWS', 'rows must be an array');
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    const cellCount = Array.isArray(row) ? row.length : 0;
    if (cellCount !== columns) {
      throw new TableError('BAD_ROW_LENGTH', `row ${i} has ${cellCount} cells, expected ${columns}`);
    }
    for (let j = 0; j < columns; j += 1) {
      if (typeof row[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }
  if (rows.length === 0) return '';

  const outputLines = [];
  let firstRowLineCount = 0;
  for (let rowIndex = 0; rowIndex < rows.length; rowIndex += 1) {
    const row = rows[rowIndex];
    const wrapped = row.map((cell, colIndex) => wrapCell(cell, widths[colIndex]));
    const lineCount = Math.max(...wrapped.map((lines) => lines.length));
    for (let lineIndex = 0; lineIndex < lineCount; lineIndex += 1) {
      const parts = wrapped.map((lines, colIndex) => {
        const text = lineIndex < lines.length ? lines[lineIndex] : '';
        return padCell(text, widths[colIndex], alignments[colIndex]);
      });
      outputLines.push(parts.join(' | '));
    }
    if (rowIndex === 0) firstRowLineCount = lineCount;
    if (header && rowIndex === 0) {
      const rule = widths.map((width) => '-'.repeat(width)).join('-+-');
      outputLines.push(rule);
    }
  }
  return outputLines.join('\n');
}"}

