  if (typeof template !== 'string') throw new Error('template must be a string');
  const parts = [];
  let literal = '';
  let i = 0;
  while (i < template.length) {
    const character = template[i];
    if (character === '{') {
      if (literal !== '') {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }
      const open = i;
      const close = template.indexOf('}', open + 1);
      if (close === -1) throw new UriTemplateError(`unterminated expression at ${open}`, open);
      parts.push(parseExpression(template.slice(open + 1, close), open));
      i = close + 1;
      continue;
    }
    if (character === '}') throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    literal += character;
    i += 1;
  }
